CREATE TABLE cashshop_catalog (tab SMALLINT UNSIGNED NOT NULL, nameid INT UNSIGNED NOT NULL, price INT UNSIGNED NOT NULL, PRIMARY KEY(tab,nameid)) ENGINE=InnoDB;
CREATE TABLE cp_rops_catalog_items (id INT UNSIGNED PRIMARY KEY, aegis VARCHAR(255) NOT NULL, name VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE cp_rops_state (id TINYINT UNSIGNED PRIMARY KEY, revision BIGINT UNSIGNED NOT NULL DEFAULT 1) ENGINE=InnoDB;
INSERT INTO cp_rops_state(id,revision) VALUES(1,1);
CREATE TABLE cp_rops_audit (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, actor INT UNSIGNED NOT NULL, action VARCHAR(20) NOT NULL, item_id INT UNSIGNED NOT NULL, tab SMALLINT UNSIGNED NOT NULL, snapshot LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
